<script>document.addEventListener('DOMContentLoaded',()=>{const input=document.getElementById('file'),zone=document.getElementById('lcl-dropzone'),title=document.getElementById('lcl-file-title'),detail=document.getElementById('lcl-file-detail');const update=files=>{if(!files?.length)return;title.textContent=files[0].name;detail.textContent=(files[0].size/1024/1024).toFixed(2)+' MB · siap diupload';zone.classList.add('has-file')};input.addEventListener('change',()=>update(input.files));['dragenter','dragover'].forEach(e=>zone.addEventListener(e,event=>{event.preventDefault();zone.classList.add('is-dragging')}));['dragleave','drop'].forEach(e=>zone.addEventListener(e,event=>{event.preventDefault();zone.classList.remove('is-dragging')}));zone.addEventListener('drop',event=>{input.files=event.dataTransfer.files;update(input.files)})});</script>
